'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const slopeTree = new Float64Array(N + 2);
const interceptTree = new Float64Array(N + 2);

function add(tree, index, value) {
  for (let i = index; i <= N + 1; i += i & -i) {
    tree[i] += value;
  }
}

function prefixSum(tree, index) {
  let sum = 0;
  for (let i = index; i > 0; i -= i & -i) {
    sum += tree[i];
  }
  return sum;
}

const output = [];

for (let q = 0; q < M; q++) {
  const type = nextInt();
  const i = nextInt();

  if (type === 3) {
    const slope = prefixSum(slopeTree, i);
    const intercept = prefixSum(interceptTree, i);
    output.push(String(slope * i + intercept));
    continue;
  }

  const V = nextInt();
  let left, right, slope, intercept;

  if (type === 1) {
    left = i;
    right = Math.min(N, i + V - 1);
    slope = -1;
    intercept = V + i;
  } else {
    left = Math.max(1, i - V + 1);
    right = i;
    slope = 1;
    intercept = V - i;
  }

  add(slopeTree, left, slope);
  add(slopeTree, right + 1, -slope);
  add(interceptTree, left, intercept);
  add(interceptTree, right + 1, -intercept);
}

process.stdout.write(output.join('\n'));
